// Sepia-Nostalgie: klassische Sepia-Matrix + Vignette + feines Korn und
// ein kaum merkliches Helligkeits-Flackern wie beim alten Projektor.
float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
vec4 farbe(vec2 uv, vec4 src)
{
    vec3 c = src.rgb;
    vec3 sepia = vec3(dot(c, vec3(0.393, 0.769, 0.189)),
                      dot(c, vec3(0.349, 0.686, 0.168)),
                      dot(c, vec3(0.272, 0.534, 0.131)));
    vec2 d = uv - 0.5;
    sepia *= 1.0 - 0.45 * dot(d, d) * 2.2;               // Vignette
    float korn = hash(uv * uResolution * 0.5 + floor(uTime * 24.0));
    sepia += (korn - 0.5) * 0.05;
    sepia *= 0.97 + 0.03 * sin(uTime * 11.0);            // Projektor-Flackern
    return vec4(clamp(sepia, 0.0, 1.0), 1.0);
}
